//! The web client's icons (assets/icons, generated by scripts/icons.py from
//! web/src/components/Icons.tsx): 24×24 outlines, stroke 2, drawn at an
//! exact pixel size. Each size and sub-pixel offset is rasterized once with
//! resvg, the way Chromium draws an inline SVG at a fractional position,
//! and tinted when painted.

use std::collections::HashMap;
use std::sync::Arc;

use egui::{Color32, ColorImage, Painter, Pos2, Rect, TextureHandle, TextureOptions, Vec2};
use parking_lot::Mutex;
use resvg::{tiny_skia, usvg};

pub use crate::icons_generated::Icon;

/// Sub-pixel offsets are kept to quarter pixels.
const STEPS: f32 = 4.0;

#[derive(Clone, Copy, Hash, PartialEq, Eq)]
struct Key {
    icon: Icon,
    /// Size in physical pixels × 4.
    size: u32,
    fx: u8,
    fy: u8,
}

#[derive(Clone, Default)]
struct Cache(Arc<Mutex<HashMap<Key, Option<TextureHandle>>>>);

fn cache(ctx: &egui::Context) -> Cache {
    ctx.data_mut(|d| {
        d.get_temp_mut_or_default::<Cache>(egui::Id::unique("gelabber-icons"))
            .clone()
    })
}

fn rasterize(icon: Icon, size_px: f32, fx: f32, fy: f32) -> Option<ColorImage> {
    let tree = usvg::Tree::from_data(icon.svg(), &usvg::Options::default()).ok()?;
    let w = (size_px + fx).ceil().max(1.0) as u32;
    let h = (size_px + fy).ceil().max(1.0) as u32;
    let mut pixmap = tiny_skia::Pixmap::new(w, h)?;
    let scale = size_px / 24.0;
    let transform = tiny_skia::Transform::from_row(scale, 0.0, 0.0, scale, fx, fy);
    resvg::render(&tree, transform, &mut pixmap.as_mut());
    Some(ColorImage::from_rgba_premultiplied(
        [w as usize, h as usize],
        pixmap.data(),
    ))
}

/// Paints `icon` as a `size`×`size` px box with its top-left at `min`
/// (CSS position, may be fractional), in `color`.
pub fn paint(painter: &Painter, icon: Icon, min: Pos2, size: f32, color: Color32) {
    let ctx = painter.ctx();
    let ppp = ctx.pixels_per_point();
    let (x, y) = (min.x * ppp, min.y * ppp);
    let (fx, fy) = (
        ((x - x.floor()) * STEPS).round() / STEPS,
        ((y - y.floor()) * STEPS).round() / STEPS,
    );
    let (x0, y0) = (
        x.floor() + (fx / 1.0).floor(),
        y.floor() + (fy / 1.0).floor(),
    );
    let (fx, fy) = (fx.fract(), fy.fract());
    let size_px = size * ppp;
    let key = Key {
        icon,
        size: (size_px * STEPS).round() as u32,
        fx: (fx * STEPS) as u8,
        fy: (fy * STEPS) as u8,
    };
    let cache = cache(ctx);
    let texture = {
        let mut map = cache.0.lock();
        map.entry(key)
            .or_insert_with(|| {
                rasterize(icon, size_px, fx, fy).map(|image| {
                    ctx.load_texture(
                        format!("icon-{icon:?}-{}", key.size),
                        image,
                        TextureOptions::NEAREST,
                    )
                })
            })
            .clone()
    };
    let Some(texture) = texture else { return };
    let [w, h] = texture.size();
    let rect = Rect::from_min_size(
        Pos2::new(x0 / ppp, y0 / ppp),
        Vec2::new(w as f32 / ppp, h as f32 / ppp),
    );
    painter.image(
        texture.id(),
        rect,
        Rect::from_min_max(Pos2::ZERO, Pos2::new(1.0, 1.0)),
        color,
    );
}

/// Paints `icon` centred in `rect`.
pub fn paint_centered(painter: &Painter, icon: Icon, rect: Rect, size: f32, color: Color32) {
    let min = rect.center() - Vec2::splat(size / 2.0);
    paint(painter, icon, min, size, color);
}

/// Allocates a `size` box at the cursor and paints `icon` in it.
pub fn show(ui: &mut egui::Ui, icon: Icon, size: f32, color: Color32) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(Vec2::splat(size), egui::Sense::hover());
    if ui.is_rect_visible(rect) {
        paint(ui.painter(), icon, rect.min, size, color);
    }
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_rasterizes() {
        for icon in Icon::ALL {
            let image = rasterize(icon, 16.0, 0.0, 0.0).expect("icon renders");
            assert!(image.pixels.iter().any(|p| p.a() > 0), "{icon:?} is empty");
        }
    }
}
